<script setup>
import {routePath,sitePath} from '../paths.js';

import {ref,onMounted,onBeforeUnmount} from 'vue';import {Blocks,LockKeyhole,ArrowRight,Eye,LoaderCircle,Maximize2,Pause,Play,ShieldCheck} from 'lucide-vue-next';import ScreenPlayer from './components/ScreenPlayer.vue';import {storeGet,resolveAssets} from './storage.js';import {validateProject} from './schema.js';import './workbench.css';import './runtime/screen.css';
const project=ref(null),assets=ref({}),playing=ref(true),loading=ref(true),error=ref(''),locked=ref(false),mode=ref('password'),password=ref(''),busy=ref(false);const slug=routePath().startsWith('/view/')?routePath().split('/')[2]:null;
function fullscreen(){document.documentElement.requestFullscreen?.();}
async function load(){loading.value=true;error.value='';try{if(!slug){const id=new URLSearchParams(location.search).get('local');const local=id&&await storeGet('projects',id);if(!local)throw Error('找不到这个本机项目，请从工作台预览');project.value=validateProject(local);assets.value=await resolveAssets(project.value.assets);return;}const response=await fetch('/api/public/'+slug);const value=await response.json();if(response.status===401){locked.value=true;mode.value=value.mode||'password';return;}if(!response.ok)throw Error(value.error||'大屏暂时无法打开');project.value=validateProject(value.project);assets.value=await resolveAssets(project.value.assets);locked.value=false;}catch(e){error.value=e.message;}finally{loading.value=false;}}
async function unlock(token){busy.value=true;error.value='';try{const response=await fetch('/api/public/'+slug+'/unlock',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(token?{token}:{password:password.value})});const value=await response.json();if(!response.ok)throw Error(value.error);password.value='';history.replaceState({},'',location.pathname);await load();}catch(e){error.value=e.message;}finally{busy.value=false;}}
onMounted(async()=>{await load();const token=new URLSearchParams(location.search).get('token');if(token&&slug)await unlock(token);});onBeforeUnmount(()=>Object.values(assets.value).forEach(URL.revokeObjectURL));
</script>
<template><main class="aw-public-viewer"><ScreenPlayer v-if="project" :project="project" :assets="assets" :playing="playing" :public-slug="slug"/><div v-else class="aw-viewer-gate"><a :href="sitePath('/')" class="aw-viewer-brand"><Blocks :size="23" :stroke-width="1.4"/>astra<span>view</span></a><template v-if="loading"><LoaderCircle :size="27" class="spin"/><p>正在打开数据大屏</p></template><form v-else-if="locked" @submit.prevent="mode==='token'?unlock(password):unlock()"><component :is="mode==='token'?ShieldCheck:LockKeyhole" :size="31" :stroke-width="1.1"/><h1>为需要的人，保留一扇门。</h1><p>{{mode==='token'?'请输入访问令牌，或使用包含令牌的完整链接。':'这个大屏已设置访问密码。'}}</p><input v-model="password" type="password" :aria-label="mode==='token'?'访问令牌':'访问密码'" :placeholder="mode==='token'?'输入访问令牌':'输入查看密码'" autocomplete="current-password" required/><p v-if="error" class="gate-error">{{error}}</p><button type="submit" :disabled="busy">{{busy?'正在验证…':'进入大屏'}}<ArrowRight :size="15"/></button></form><div v-else class="aw-viewer-error"><h1>暂时无法打开这个大屏</h1><p>{{error}}</p><button @click="load">重新加载</button><a :href="sitePath('/')">返回工作台</a></div></div><div v-if="project" class="aw-viewer-controls"><button :aria-label="playing?'暂停动效':'播放动效'" @click="playing=!playing"><component :is="playing?Pause:Play" :size="14"/></button><button aria-label="全屏查看" @click="fullscreen"><Maximize2 :size="14"/></button><a :href="sitePath('/')" title="使用 Astra Studio 创作"><Blocks :size="14"/></a></div></main></template>
<style>.aw-public-viewer{height:100dvh;overflow:hidden;background:#06141f;font-family:Inter,'PingFang SC',sans-serif;color:#d2e8dd}.aw-public-viewer *{box-sizing:border-box}.aw-viewer-gate{width:100%;height:100%;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:20px;background:radial-gradient(ellipse at 50% 45%,#113128,#06141f 70%);position:relative}.aw-viewer-brand{position:absolute;left:35px;top:30px;display:flex;align-items:center;gap:9px;font-size:22px;letter-spacing:-.9px;color:#d0e4d4}.aw-viewer-brand>span{font-weight:300;color:#709e87}.aw-viewer-gate>p{font-size:12px;color:#668c7c}.aw-viewer-gate>form{width:min(350px,85vw);display:flex;flex-direction:column;align-items:center;text-align:center}.aw-viewer-gate form>svg{color:#80b096;margin-bottom:27px}.aw-viewer-gate h1{font-size:19px;font-weight:400;letter-spacing:1px;color:#a4c4ae;margin:0}.aw-viewer-gate form>p{font-size:11px;color:#648875;line-height:1.9;margin:15px 0 25px}.aw-viewer-gate input{border:1px solid #375445;background:#0e261e;border-radius:5px;padding:13px;color:#b4d2bb;font-size:12px;width:100%;outline:none}.aw-viewer-gate input:focus{border-color:#6ca582}.aw-viewer-gate input::placeholder{color:#42644e}.aw-viewer-gate form>button{display:flex;align-items:center;justify-content:center;gap:15px;width:100%;padding:12px;margin-top:15px;border:1px solid #4c8b67;border-radius:5px;background:#387751;color:#c8e9ce;font-size:12px}.aw-viewer-gate form>.gate-error{color:#c59a7d;font-size:11px;margin:12px 0 0}.aw-viewer-error{text-align:center;max-width:85vw}.aw-viewer-error>p{font-size:12px;color:#668e77;line-height:1.9;margin:20px 0}.aw-viewer-error>button{border:1px solid #375a46;padding:9px 22px;color:#86b193;border-radius:5px;background:none;cursor:pointer}.aw-viewer-error>a{font-size:11px;display:block;margin-top:20px;color:#517960}.aw-viewer-controls{position:fixed;right:22px;bottom:18px;display:flex;align-items:center;gap:7px;background:#0f2a24bb;border:1px solid #47705a33;border-radius:6px;padding:4px;opacity:0;transition:opacity .2s}.aw-public-viewer:hover>.aw-viewer-controls,.aw-viewer-controls:focus-within{opacity:1}.aw-viewer-controls>button,.aw-viewer-controls>a{display:grid;place-items:center;height:27px;width:27px;color:#7eaa8a;border:0;background:none;border-radius:3px;cursor:pointer}.aw-viewer-controls>button:hover,.aw-viewer-controls>a:hover{background:#22432e}.aw-viewer-gate .spin{color:#669575}@media(prefers-reduced-motion:reduce){.aw-viewer-controls{transition:none}}</style>
